 Future<void> _addAlert() async { if (widget.controller.data.favourites.isEmpty) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Save a product before creating an alert.'))); return; } final price = TextEditingController(); var product = widget.controller.data.favourites.first; final alert = await showDialog<PriceAlert>(context: context, builder: (context) => AlertDialog(title: const Text('Target price alert'), content: Column(mainAxisSize: MainAxisSize.min, children: [DropdownButtonFormField(value: product, items: widget.controller.data.favourites.map((item) => DropdownMenuItem(value: item, child: Text(item.displayName))).toList(), onChanged: (value) => product = value!), TextField(controller: price, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Target price', prefixText: '₹ '))]), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { final target = double.tryParse(price.text); if (target == null || target <= 0) return; Navigator.pop(context, PriceAlert(product: product, targetPrice: target)); }, child: const Text('Save'))])); if (alert != null) await widget.controller.save(widget.controller.data.copyWith(alerts: [...widget.controller.data.alerts.where((item) => item.product.id != alert.product.id), alert])); }
